const goldenLinuxDryRun = `Dry run: nothing is written, removed or run.

Would write /cfg/systemd/user/tbd-test-golden.service (mode 0644):
# Generated by ` + "`tbd install`; `tbd uninstall`" + ` removes it.
[Unit]
Description=Teams Bridge daemon (tbd): Teams notifications to your phone
Documentation=https://github.com/alien2003/teams-bridge

[Service]
Type=exec
ExecStart="/opt/tbd dir/tbd" run --home "/srv/tbd home"
Restart=always
RestartSec=10
KillMode=mixed
TimeoutStopSec=30

[Install]
WantedBy=default.target
(end of /cfg/systemd/user/tbd-test-golden.service)

Would run:
  systemctl --user daemon-reload
  systemctl --user enable tbd-test-golden.service
  systemctl --user restart tbd-test-golden.service

tbd-test-golden.service starts with your user session; install also (re)starts it now.
Status: systemctl --user status tbd-test-golden.service; logs: journalctl --user -u tbd-test-golden.service -f

To run it without a login session (headless machine): loginctl enable-linger alice
`

const goldenLinuxUninstallDryRun = `Dry run: nothing is written, removed or run.

Would run:
  systemctl --user disable --now tbd-test-golden.service

Would remove:
  /cfg/systemd/user/tbd-test-golden.service

Then would run:
  systemctl --user daemon-reload
`

// noRunner fails the test if anything is run.
type noRunner struct{ t *testing.T }

func (n noRunner) Run(_ context.Context, name string, args ...string) (string, error) {
	n.t.Errorf("dry run executed %s %v", name, args)
	return "", errors.New("must not run")
}

func dryRun(t *testing.T, p Plan) string {
	t.Helper()
	var buf bytes.Buffer
	if err := Apply(context.Background(), p, noRunner{t}, &buf, true); err != nil {
		t.Fatal(err)
	}
	return buf.String()
}

func TestDryRunLinuxExact(t *testing.T) {
	env := envOf(map[string]string{"XDG_CONFIG_HOME": "/cfg", "USER": "alice"})
	spec := Spec{Name: "tbd-test-golden", Exe: "/opt/tbd dir/tbd", Home: "/srv/tbd home"}
	p, err := InstallPlan(spec, "linux", env)
	if err != nil {
		t.Fatal(err)
	}
	if got := dryRun(t, p); got != goldenLinuxDryRun {
		t.Errorf("install dry run\n--- got\n%s--- want\n%s", got, goldenLinuxDryRun)
	}
	u, _ := UninstallPlan(spec, "linux", env)
	if got := dryRun(t, u); got != goldenLinuxUninstallDryRun {
		t.Errorf("uninstall dry run\n--- got\n%s--- want\n%s", got, goldenLinuxUninstallDryRun)
	}
	// Paths with blanks are shell-quoted, one command per line.
	r, _ := InstallPlan(Spec{Name: "x", Exe: "/bin/true", Runtime: true}, "linux", envOf(map[string]string{"XDG_CONFIG_HOME": "/cfg dir"}))
	if got := dryRun(t, r); !strings.Contains(got, "\n  systemctl --user --runtime link '/cfg dir/systemd/user/x.service'\n") {
		t.Errorf("runtime dry run:\n%s", got)
	}
}

func TestDryRunWindowsExact(t *testing.T) {
	spec := Spec{Exe: `C:\Program Files\tbd\tbd.exe`, Home: `C:\Users\alice\tbd data`}
	p, err := InstallPlan(spec, "windows", winEnv)
	if err != nil {
		t.Fatal(err)
	}
	x, _ := TaskXML(spec, `PC\alice`)
	want := "Dry run: nothing is written, removed or run.\n\n" +
		`Would write C:\Users\alice\tbd data\tbd.task.xml (mode 0644, UTF-16LE with BOM, shown decoded):` + "\n" +
		decodeText(x) +
		`(end of C:\Users\alice\tbd data\tbd.task.xml)` + "\n\n" +
		"Would run:\n" +
		`  schtasks /create /tn tbd /xml "C:\Users\alice\tbd data\tbd.task.xml" /f` + "\n" +
		"  schtasks /run /tn tbd\n\n" +
		`Task tbd starts tbd hidden (conhost --headless) at every logon of PC\alice; install also starts it now.` + "\n" +
		"Status: schtasks /query /tn tbd /v /fo list; stop: schtasks /end /tn tbd\n"
	if got := dryRun(t, p); got != want {
		t.Errorf("windows dry run\n--- got\n%s--- want\n%s", got, want)
	}
	if !strings.Contains(decodeText(x), "\r\n    <ExecutionTimeLimit>PT0S</ExecutionTimeLimit>\r\n") {
		t.Error("decoded XML lacks CRLF lines")
	}
}

// hostPlan is an install plan for the host OS whose every path is under dir.
func hostPlan(t *testing.T, dir string) (Spec, Env) {
	t.Helper()
	if runtime.GOOS == "windows" {
		return Spec{Name: "tbd-test-apply", Exe: `C:\nonexistent\tbd.exe`, Home: filepath.Join(dir, "home dir")}, winEnv
	}
	return Spec{Name: "tbd-test-apply", Exe: "/nonexistent/tbd", Home: filepath.Join(dir, "home")},
		envOf(map[string]string{"XDG_CONFIG_HOME": filepath.Join(dir, "cfg dir"), "USER": "u"})
}

func listTree(t *testing.T, dir string) []string {
	t.Helper()
	var out []string
	err := filepath.WalkDir(dir, func(p string, _ fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if p != dir {
			out = append(out, p)
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	return out
}

func TestDryRunTouchesNothing(t *testing.T) {
	dir := t.TempDir()
	spec, env := hostPlan(t, dir)
	for _, mk := range []func(Spec, string, Env) (Plan, error){InstallPlan, UninstallPlan} {
		p, err := mk(spec, runtime.GOOS, env)
		if err != nil {
			t.Fatal(err)
		}
		out := dryRun(t, p)
		for _, f := range p.Files {
			if !strings.Contains(out, "Would write "+f.Path+" (mode 0644") {
				t.Errorf("dry run does not show %s:\n%s", f.Path, out)
			}
		}
		if got := listTree(t, dir); len(got) != 0 {
			t.Errorf("dry run created %q", got)
		}
	}
}

func TestApplyHostPlan(t *testing.T) {
	dir := t.TempDir()
	spec, env := hostPlan(t, dir)
	p, err := InstallPlan(spec, runtime.GOOS, env)
	if err != nil {
		t.Fatal(err)
	}
	r := &fakeRunner{}
	var out bytes.Buffer
	if err := Apply(context.Background(), p, r, &out, false); err != nil {
		t.Fatal(err)
	}
	equalLines(t, "commands", r.calls, cmdLines(p.Commands))
	f := p.Files[0]
	got, err := os.ReadFile(f.Path)
	if err != nil || !bytes.Equal(got, f.Content) {
		t.Fatalf("file %s: %v", f.Path, err)
	}
	if st, _ := os.Stat(f.Path); runtime.GOOS != "windows" && st.Mode().Perm() != 0o644 {
		t.Errorf("mode %v", st.Mode())
	}
	if !strings.Contains(out.String(), "Wrote "+f.Path) || !strings.Contains(out.String(), p.Notes[0]) {
		t.Errorf("output:\n%s", out.String())
	}
	if left := listTree(t, filepath.Dir(f.Path)); len(left) != 1 {
		t.Errorf("temporary files left: %q", left)
	}
	// Re-install overwrites.
	if err := Apply(context.Background(), p, &fakeRunner{}, nil, false); err != nil {
		t.Fatal(err)
	}

	u, err := UninstallPlan(spec, runtime.GOOS, env)
	if err != nil {
		t.Fatal(err)
	}
	r = &fakeRunner{}
	if err := Apply(context.Background(), u, r, nil, false); err != nil {
		t.Fatal(err)
	}
	equalLines(t, "uninstall commands", r.calls, append(cmdLines(u.Commands), cmdLines(u.PostCommands)...))
	if _, err := os.Stat(f.Path); !errors.Is(err, os.ErrNotExist) {
		t.Errorf("%s not removed: %v", f.Path, err)
	}
	// Uninstalling twice: the file is already gone, which is fine.
	if err := Apply(context.Background(), u, &fakeRunner{}, nil, false); err != nil {
		t.Errorf("second uninstall: %v", err)
	}
}

// hookRunner calls fn for every command.
type hookRunner func(line string) (string, error)

func (h hookRunner) Run(_ context.Context, name string, args ...string) (string, error) {
	return h(strings.Join(append([]string{name}, args...), " "))
}

func TestApplyOrderAndFailure(t *testing.T) {
	dir := t.TempDir()
	newFile := filepath.Join(dir, "sub", "new.txt")
	oldFile := filepath.Join(dir, "old.txt")
	if err := os.WriteFile(oldFile, []byte("x"), 0o600); err != nil {
		t.Fatal(err)
	}
	exists := func(p string) bool { _, err := os.Stat(p); return err == nil }
	p := Plan{
		Files:        []File{{Path: newFile, Content: []byte("hello\n")}},
		Commands:     [][]string{{"first"}, {"second", "x y"}, {"third"}},
		RemoveFiles:  []string{oldFile, filepath.Join(dir, "missing")},
		PostCommands: [][]string{{"post"}},
		Notes:        []string{"NOTE"},
	}
	var calls []string
	r := hookRunner(func(line string) (string, error) {
		calls = append(calls, line)
		switch line {
		case "first":
			if !exists(newFile) {
				t.Error("command ran before the file was written")
			}
		case "post":
			if exists(oldFile) {
				t.Error("post command ran before the removal")
			}
		}
		return "out of " + line, nil
	})
	var out bytes.Buffer
	if err := Apply(context.Background(), p, r, &out, false); err != nil {
		t.Fatal(err)
	}
	equalLines(t, "order", calls, []string{"first", "second x y", "third", "post"})
	if exists(oldFile) {
		t.Error("old file not removed")
	}
	for _, want := range []string{"Running: second 'x y'\n  out of second x y\n", "Removed " + oldFile, "\nNOTE\n"} {
		if !strings.Contains(out.String(), want) {
			t.Errorf("output lacks %q:\n%s", want, out.String())
		}
	}

	// Without BestEffort the first failure stops everything and carries the output.
	calls = nil
	r = hookRunner(func(line string) (string, error) {
		calls = append(calls, line)
		if line == "second x y" {
			return "Failed to enable unit: boom\n", errors.New("exit status 1")
		}
		return "", nil
	})
	out.Reset()
	err := Apply(context.Background(), p, r, &out, false)
	if err == nil || !strings.Contains(err.Error(), "boom") || !strings.Contains(err.Error(), "exit status 1") {
		t.Fatalf("err = %v", err)
	}
	equalLines(t, "stopped", calls, []string{"first", "second x y"})
	if strings.Contains(out.String(), "NOTE") {
		t.Error("notes printed after a failed install")
	}

	// BestEffort: every step runs, all errors are returned.
	if err := os.WriteFile(oldFile, []byte("x"), 0o600); err != nil {
		t.Fatal(err)
	}
	p.BestEffort = true
	calls = nil
	r = hookRunner(func(line string) (string, error) {
		calls = append(calls, line)
		if line == "first" || line == "post" {
			return "nope " + line, errors.New("exit status 5")
		}
		return "", nil
	})
	out.Reset()
	err = Apply(context.Background(), p, r, &out, false)
	if err == nil || !strings.Contains(err.Error(), "nope first") || !strings.Contains(err.Error(), "nope post") {
		t.Fatalf("err = %v", err)
	}
	equalLines(t, "best effort", calls, []string{"first", "second x y", "third", "post"})
	if exists(oldFile) {
		t.Error("best effort did not remove the file after a failed command")
	}
	if !strings.Contains(out.String(), "NOTE") {
		t.Error("best effort did not print notes")
	}
}

func TestApplyEmptyCommand(t *testing.T) {
	err := Apply(context.Background(), Plan{Commands: [][]string{{}}}, noRunner{t}, nil, false)
	if err == nil || !strings.Contains(err.Error(), "empty command") {
		t.Errorf("err = %v", err)
	}
}

func TestDryRunShowsUnterminatedContent(t *testing.T) {
	got := DryRunText(Plan{Files: []File{{Path: "/x", Content: []byte("no newline"), Mode: 0o600}}})
	want := "Dry run: nothing is written, removed or run.\n\nWould write /x (mode 0600):\nno newline\n(end of /x)\n"
	if got != want {
		t.Errorf("got %q", got)
	}
}
